import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:shared_preferences/shared_preferences.dart';

/// One food from the bundled list (assets/foods/foods.json, generated by
/// tool/foods/build_foods.py). Values are per portion and approximate.
class FoodItem {
  final String id;
  final String en;
  final String ur;
  final String portionEn;
  final String portionUr;
  final int grams;
  final int kcal;
  final double protein;
  final double carbs;
  final double fat;
  final List<String> aliases;

  const FoodItem({
    required this.id,
    required this.en,
    required this.ur,
    required this.portionEn,
    required this.portionUr,
    required this.grams,
    required this.kcal,
    required this.protein,
    required this.carbs,
    required this.fat,
    this.aliases = const [],
  });

  factory FoodItem.fromMap(Map<String, dynamic> m) => FoodItem(
        id: m['id'] as String,
        en: m['en'] as String,
        ur: m['ur'] as String,
        portionEn: m['portionEn'] as String,
        portionUr: m['portionUr'] as String,
        grams: m['grams'] as int,
        kcal: m['kcal'] as int,
        protein: (m['protein'] as num).toDouble(),
        carbs: (m['carbs'] as num).toDouble(),
        fat: (m['fat'] as num).toDouble(),
        aliases: [for (final a in (m['aliases'] as List? ?? const [])) a as String],
      );

  String name(String locale) => locale == 'ur' ? ur : en;
  String portion(String locale) => locale == 'ur' ? portionUr : portionEn;
}

class FoodCatalog {
  final List<FoodItem> foods;
  const FoodCatalog(this.foods);

  static FoodCatalog parse(String json) {
    final m = jsonDecode(json) as Map<String, dynamic>;
    return FoodCatalog([
      for (final f in m['foods'] as List) FoodItem.fromMap(f as Map<String, dynamic>)
    ]);
  }

  static Future<FoodCatalog>? _bundled;

  /// The bundled list, loaded once.
  static Future<FoodCatalog> load() => _bundled ??=
      rootBundle.loadString('assets/foods/foods.json').then(parse);

  FoodItem? byId(String id) {
    for (final f in foods) {
      if (f.id == id) return f;
    }
    return null;
  }

  /// Foods matching [query] in English, Urdu or an alias. Word-start matches
  /// come first, then foods used more often ([usage]), then by name.
  /// An empty query returns the most-used foods only.
  List<FoodItem> search(String query, {Map<String, int> usage = const {}, int limit = 8}) {
    final q = query.trim().toLowerCase();
    int used(FoodItem f) => usage[f.id] ?? 0;
    if (q.isEmpty) {
      final recent = foods.where((f) => used(f) > 0).toList()
        ..sort((a, b) => used(b).compareTo(used(a)));
      return recent.take(limit).toList();
    }
    final scored = <(FoodItem, int)>[];
    for (final f in foods) {
      final texts = [f.en.toLowerCase(), f.ur, ...f.aliases.map((a) => a.toLowerCase())];
      var score = -1;
      for (final t in texts) {
        if (t.startsWith(q)) {
          score = 2;
          break;
        }
        if (t.split(RegExp(r'[\s()\-,]+')).any((w) => w.startsWith(q))) {
          score = score < 1 ? 1 : score;
        } else if (t.contains(q)) {
          score = score < 0 ? 0 : score;
        }
      }
      if (score >= 0) scored.add((f, score));
    }
    scored.sort((a, b) {
      final s = b.$2.compareTo(a.$2);
      if (s != 0) return s;
      final u = used(b.$1).compareTo(used(a.$1));
      return u != 0 ? u : a.$1.en.compareTo(b.$1.en);
    });
    return scored.take(limit).map((e) => e.$1).toList();
  }
}

/// How often each food was logged, kept on the device for "recent first".
class FoodUsage {
  static const key = 'food_usage';

  static Future<Map<String, int>> load() async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(key);
    if (raw == null) return {};
    try {
      return (jsonDecode(raw) as Map<String, dynamic>)
          .map((k, v) => MapEntry(k, (v as num).toInt()));
    } on FormatException {
      return {};
    }
  }

  static Future<void> record(String id) async {
    final prefs = await SharedPreferences.getInstance();
    final usage = await load();
    usage[id] = (usage[id] ?? 0) + 1;
    await prefs.setString(key, jsonEncode(usage));
  }
}
